namespace Sdt.Run {
 public class ClassProgress{public int lv=1,xp;}
 public class StashStack{public string variantKey;public CardDef card;public int count;}
 public class InventorySlot:InvSlot{}
 public class BaseStats{public int extracts,deaths,stashTotal;}
 public class BaseData{public int cap=99,wood,rations;public BaseStats stats=new BaseStats();public ClassProgress progress=new ClassProgress{lv=1,xp=45};public List<StashStack> stash=new List<StashStack>(),pocket=new List<StashStack>();public Dictionary<string,int> collection=new Dictionary<string,int>();public int StashUsed=>stash.Sum(s=>s.count);public int StashCap=>cap;public int StashRoom=>Math.Max(0,cap-StashUsed);public static bool IsSha(CardDef c)=>c.id=="starter";public void Deposit(IEnumerable<InventorySlot> items){foreach(var i in items){if(i.name=="木材")wood+=i.count;if(i.name=="口粮")rations+=i.count;}}public void DepositCards(IEnumerable<StashStack> entries,bool toPocket=false){var target=toPocket?pocket:stash;foreach(var e in entries.Where(s=>!IsSha(s.card)&&(!toPocket||s.card.rarity!="职业"))){var match=target.FirstOrDefault(s=>CurrentSettlementLogic.SourceKey(s)==CurrentSettlementLogic.SourceKey(e));if(match==null)target.Add(CurrentSettlementLogic.Copy(e));else match.count+=e.count;}}}
 public class MetaProgress{GameRuntime g;public const int LevelMax=10;public static int XpForNext(int lv)=>50+(Math.Max(1,lv)-1)*40;public MetaProgress(GameRuntime v){g=v;}public int ClassLv(string cls)=>g.Base.progress.lv;public int ClassXP(string cls)=>g.Base.progress.xp;public class TrackData{public int? coins,actions,count;public string cls;}public void Track(string kind,TrackData data){if(kind=="stash")g.Base.stats.stashTotal+=data.count??0;int xp=0;if(kind=="extract"){g.Base.stats.extracts++;xp=CurrentSettlementLogic.ExtractionXp(data.actions??0,g.ModeCfg.xpMul);}if(kind=="death"){g.Base.stats.deaths++;xp=5;}var p=g.Base.progress;if(p.lv>=10)return;p.xp+=xp;while(p.lv<10&&p.xp>=XpForNext(p.lv)){p.xp-=XpForNext(p.lv);p.lv++;}}}
 public class SettlementRecord{public string identity,reason,status;public RunSaveData run;public List<StashStack> left=new List<StashStack>(),keptPocket=new List<StashStack>();public ExtractResult extraction;public DeathResult death;public AbandonResult abandon;public int sourceIdentityVersion,requestSeq,totalPocketCount,lostPocketCount;public RunGrowthReceipt growth;public SettlementReceipt receipt;}
 public class RunSaveData{}
 public class ExtractResult{public int WoodN,RatN,ShaN,OtherN,Actions,Hp,MaxHp,Coins,StashUsed,StashCap,StashRoom,CollectionCount,PocketKept,PocketLost,PocketRuleLost;public long TotalValue;public string TimeStr;public bool Done;public List<StashStack> Left,SavedCards,KeptPocket;public SettlementReceipt Receipt;public RunGrowthReceipt Growth;}
 public class DeathResult{public long LostValue;public List<StashStack> SavedStacks;public int SavedN;public SettlementReceipt Receipt;public RunGrowthReceipt Growth;}
 public class AbandonResult{public int BroughtN,KeptN,Coins;public List<StashStack> KeptStacks;public SettlementReceipt Receipt;}
 public class ExtractStashChanged{public ExtractResult Result;}public class RunEnded{public string Reason;}public class Bus{public void Emit(object value){}}public class Audio{public void PlaySfx(string s){}public void PlayBgm(string s){}}
 public static class CardContainerCommands{public const string PearlId="pearl";}
 public static class SaveJson{public static string Stringify(object o)=>JsonConvert.SerializeObject(o);public static T Read<T>(string s)=>JsonConvert.DeserializeObject<T>(s);}
 public class Saves{public SettlementRecord record;public bool run=true;public void PutSettlement(int slot,SettlementRecord value){record=SaveJson.Read<SettlementRecord>(SaveJson.Stringify(value));}public void RemoveRun(int slot){run=false;}}
 public class Mode{public double xpMul=1.5;}
 public sealed partial class GameRuntime {
  public RunState State=new RunState();public BaseData Base=new BaseData();public MetaProgress Meta;public Rng Rng=new Rng(12345);public Saves Saves=new Saves();public int? ActiveSlot=1;public Bus Bus=new Bus();public Audio Audio=new Audio();public MapModel Map=new MapModel();public Mode ModeCfg=new Mode();public bool FailOnce;
  public GameRuntime(){Meta=new MetaProgress(this);Map.CellDefs["0,0"]=new MapNode{layerIdx=0};Map.CellDefs["1,0"]=new MapNode{layerIdx=1};}
  string RunIdentity=>(ActiveSlot??State.slot)+":"+(State.seed??0);SettlementRecord ActiveSettlement()=>Saves.record?.identity==RunIdentity?SaveJson.Read<SettlementRecord>(SaveJson.Stringify(Saves.record)):null;bool IsPendingExtraction(SettlementRecord r)=>r?.reason=="extract"&&r.status=="sorting";void SyncPlayTime(){}void ClearBattleCheckpoint(){}RunSaveData CaptureRunSave()=>new RunSaveData();
  public bool TryPersistMutation(Action action,out string reason){string before=SaveJson.Stringify(new{State,Base,Saves,left=_extractLeft}),rng=Rng.SaveState();try{action();if(FailOnce){FailOnce=false;throw new System.IO.IOException("disk full");}reason=null;return true;}catch(Exception e){var saved=JObject.Parse(before);State=saved["State"].ToObject<RunState>();Base=saved["Base"].ToObject<BaseData>();Saves=saved["Saves"].ToObject<Saves>();_extractLeft=saved["left"].ToObject<List<StashStack>>();Rng.LoadState(rng);reason=e.Message;return false;}}
 }
}
class Program {
 static int n;static void Check(bool ok,string label){if(!ok)throw new Exception(label);n++;}static CardDef A=new CardDef{id="a",name="同名",rarity="稀有",variantKey="red",sell=5},B=new CardDef{id="b",name="同名",rarity="史诗",variantKey="blue",sell=5},Sha=new CardDef{id="starter",name="初始攻击",rarity="古朴"},Career=new CardDef{id="career",name="职业牌",rarity="职业"};
 static GameRuntime Game(){var g=new GameRuntime();g.State.ownedCards=new List<OwnedCard>{new OwnedCard{uid="a1",card=A,brought=1},new OwnedCard{uid="a2",card=A,safe=true},new OwnedCard{uid="b1",card=B},new OwnedCard{uid="b2",card=B},new OwnedCard{uid="sha",card=Sha}};g.State.usedPocket=new List<PocketStack>{new PocketStack{card=A,count=3},new PocketStack{card=Sha,count=2},new PocketStack{card=Career,count=1}};g.State.inventory=new List<InvSlot>{new InvSlot{name="木材",count=3},new InvSlot{name="口粮",count=2}};return g;}
 static void Main(string[] args){var source=JObject.Parse(System.IO.File.ReadAllText(args[0]));var g=Game();Check(CurrentSettlementLogic.SourceKey(new StashStack{card=A,count=1})==(string)source["keys"][0],"source key parity");Check(CurrentSettlementLogic.ExtractionXp(2,1.5)==(int)source["xp"][1],"xp source parity");var rng=new Rng(12345);foreach(double expected in source["rolls"].Values<double>())Check(rng.Random("pocket")==expected,"pocket-stream source parity");
  Check(CurrentSettlementLogic.SourceKey(new StashStack{card=A,variantKey="",count=1})==CurrentSettlementLogic.SourceKey(new StashStack{card=A,count=1}),"empty outer variant falls back to card like source");
  string rngBefore=g.Rng.SaveState();g.FailOnce=true;Check(g.DoExtract()==null&&g.Saves.record==null&&g.Saves.run&&g.State.runActive&&g.Base.stats.extracts==0&&g.Base.progress.xp==45&&g.Rng.SaveState()==rngBefore,"failed start rolls back base/run/XP/RNG/receipt");var start=g.DoExtract();Check(start.Left.Count==2&&start.Left.Sum(s=>s.count)==4,"same-name variants stay distinct");Check(g.Saves.record.sourceIdentityVersion==1&&g.Saves.record.totalPocketCount==6,"roll snapshot persisted");int keep=source["rolls"].Values<double>().Count(v=>v<1.0/3);Check(g.Saves.record.keptPocket.Sum(s=>s.count)==keep,"all original rolls retained including rule losses");Check(g.Base.stats.extracts==1&&start.Growth.actualXp==36&&g.Base.progress.lv==2&&g.Base.progress.xp==31,"one extraction growth receipt");g.DoExtract();Check(g.Base.stats.extracts==1&&g.Base.progress.xp==31,"reopening start no XP replay");Check(g.FinishExtract()==null&&!g.CurrentExtraction.Done,"unclaimed finish requires explicit confirmation");
  Check(g.ExtractStore(new[]{new ExtractionSelection{name="同名",count=1}})==null&&g.Base.StashUsed==0,"ambiguous same-name selection rejected without source key");
  g.Base.cap=1;var picks=CurrentSettlementLogic.SelectOrdered(start.Left,1,"value");Check(picks.Count==1&&picks[0].sourceKey==CurrentSettlementLogic.SourceKey(new StashStack{card=A,count=1}),"equal-value source order stable");Check(CurrentSettlementLogic.SelectOrdered(start.Left,1,"rarity")[0].sourceKey.Contains("blue"),"rarity orders independently from original index");
  g.FailOnce=true;Check(g.ExtractStore(picks)==null&&g.Base.StashUsed==0&&g.CurrentExtraction.Left.Sum(s=>s.count)==4,"failed deposit retains original cards");var deposit=g.ExtractStore(picks);Check(deposit.StashUsed==1&&deposit.Left.Sum(s=>s.count)==3&&deposit.SavedCards.Sum(s=>s.count)==1&&deposit.SavedCards[0].card.id=="a","partial deposit true source delta");Check(g.ExtractStore(picks,"stale",1)==null&&g.Base.StashUsed==1,"stale identity no mutation");g.FailOnce=true;Check(g.FinishExtract(true)==null&&g.Saves.record.status=="sorting"&&g.CurrentExtraction.Left.Sum(s=>s.count)==3,"failed finish retains organizing page and cards");var done=g.FinishExtract(true);Check(done.Done&&done.Receipt.netTake.cardsStashed==1&&done.Receipt.losses.lostCount==3&&done.Receipt.savedCards[0].card.id=="a","finish keeps true saved/lost receipt before discard");int xp=g.Base.progress.xp;Check(g.FinishExtract(true).Receipt.losses.lostCount==3&&g.Base.progress.xp==xp,"finish replay retains exact receipt and growth");
  var dead=Game();dead.FailOnce=true;Check(dead.DoDeath()==null&&dead.Base.stats.deaths==0&&dead.Saves.run,"failed death remains recoverable");var review=new SettlementBattleReview{round=3,foes=new List<SettlementBattleFoe>{new SettlementBattleFoe{name="敌人",hp=2,maxHp=8}}};var death=dead.DoDeath(review,"战斗中生命归零");review.foes[0].hp=99;Check(death.Receipt.battleReview.foes[0].hp==2&&death.Receipt.endReason=="战斗中生命归零","death review deep snapshot");Check(death.SavedN==1&&death.Receipt.netTake.cardsStashed==1&&death.Receipt.firstExplore.xp==0&&death.Growth.actualXp==5&&dead.Base.stats.deaths==1,"death rescue and separate five XP");dead.DoDeath();Check(dead.Base.stats.deaths==1,"death reward idempotency");
  Check(done.Receipt.netTake.wood==(int)source["receipt"]["netTake"]["wood"]&&done.Receipt.netTake.rations==(int)source["receipt"]["netTake"]["rations"]&&done.Receipt.firstExplore.xp==(int)source["receipt"]["firstExplore"]["xp"],"receipt resources and exploration XP match current source vectors");
  Check(done.Receipt.netTake.cardsStashed==(int)source["receipt"]["netTake"]["cardsStashed"]&&done.Receipt.losses.lostCount==(int)source["receipt"]["losses"]["lostCount"]&&done.Receipt.savedCards[0].card.id==(string)source["receipt"]["savedCards"][0]["card"]["id"],"saved/lost exact source receipt vector");
  var maxed=Game();maxed.Base.progress=new ClassProgress{lv=10,xp=18};var capped=maxed.DoExtract();Check(capped.Growth.actualXp==0&&capped.Growth.overflowXp==36&&maxed.Base.progress.xp==18,"capped growth reports actual and overflow without replay");
  var twin=Game();twin.State.ownedCards.Add(new OwnedCard{uid="a3",card=A,safe=true});var twins=twin.DoDeath();Check(twins.SavedN==2&&twins.SavedStacks.Count==2&&twins.Receipt.losses.lostCount==4,"duplicate rescued identities keep individual source receipts");
  var abandoned=Game();abandoned.State.battleActive=true;Check(abandoned.AbandonRun()==null&&abandoned.State.runActive,"battle abandon rejects unavailable spent list");var abandon=abandoned.AbandonRun(new[]{"a2"});Check(abandon.KeptN==0&&abandoned.Base.progress.xp==45&&abandoned.Base.stats.deaths==0,"spent safe card excluded and abandon gives no death XP");abandoned.AbandonRun(new string[0]);Check(abandoned.Base.stats.deaths==0,"abandon replay no reward");Console.WriteLine("PASS "+n+" source-vector and shipping-command assertions (atomic failure boundary supplied by managed harness)");
 }
